from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _nvl_number(row: dict[str, Any], key: str) -> Decimal:
    value = row.get(key, "")
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, str) and not value.strip():
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def _numeric_equal(value: Any, expected: Decimal) -> bool:
    if value is None or value == "":
        actual = Decimal("0")
    elif isinstance(value, str) and not value.strip():
        actual = Decimal("0")
    else:
        actual = Decimal(str(value))
    return actual == expected


def transition_invoiced(
    order: dict,
    new_status: str,
) -> tuple[dict, list[str], list[str]]:
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated = dict(order)

    if new_status == "X":
        updated["STAT_CD"] = "X"
        return updated, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return updated, [], []

    raise BusinessRuleViolation(
        "E5003",
        "Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict,
    lines: list[dict],
) -> tuple[dict, list[dict], list[str]]:
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]

    if order.get("STAT_CD") in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        quantity = _nvl_number(line, "QTY")
        unit_price = _nvl_number(line, "UNIT_PRC")
        extension = _round_cents(quantity * unit_price)
        line["EXT_AMT"] = float(extension)
        total += extension

    discount = _nvl_number(order, "DISC_PCT")
    total_amount = _round_cents(total * (Decimal("100") - discount) / Decimal("100"))

    audits: list[str] = []
    if not _numeric_equal(order.get("TOT_AMT", ""), total_amount):
        audits.append("ORD_RETOTAL")

    updated_order["TOT_AMT"] = float(total_amount)
    return updated_order, updated_lines, audits
